package com.storage.lifecycle.consumer;

import com.storage.lifecycle.entity.StoredFileRecord;
import com.storage.lifecycle.event.FilePurgeCommand;
import com.storage.lifecycle.repository.StoredFileRepository;
import com.storage.lifecycle.service.BlobStorageClient;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.messaging.handler.annotation.Header;
import org.springframework.messaging.handler.annotation.Payload;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Component;

@Component
public class FileRetentionConsumer {

    private static final Logger log = LoggerFactory.getLogger(FileRetentionConsumer.class);
    private final StoredFileRepository fileRepository;
    private final BlobStorageClient blobClient;

    public FileRetentionConsumer(StoredFileRepository fileRepository, BlobStorageClient blobClient) {
        this.fileRepository = fileRepository;
        this.blobClient = blobClient;
    }

    @KafkaListener(topics = "tenant-storage-purge", groupId = "blob-lifecycle-engine")
    public void handleFilePurge(
            @Payload FilePurgeCommand command,
            @Header(name = "X-Requesting-Org", required = true) String requestingOrg) {
        StoredFileRecord fileRecord = fileRepository.findById(command.getFileId())
                .orElseThrow(() -> new IllegalArgumentException("File record not found"));
        if (!fileRecord.getOrganizationId().equals(requestingOrg)) {
            log.warn("Rejecting unauthorized file purge: Org {} tried to delete file {} owned by {}", requestingOrg, command.getFileId(), fileRecord.getOrganizationId());
            throw new AccessDeniedException("Requesting organization is not authorized to purge this file");
        }
        blobClient.deleteBlob(fileRecord.getS3Key());
        fileRepository.delete(fileRecord);
    }
}
